insert into public.assessment_questions (kind, lesson_id, unit_id, course_id, prompt, choices, correct_choice_id, hint, order_index) values
  ('quick_check', 'e8a19e11-9f80-419e-9b7c-95b26fc5d7d0', null, null, '{"en": "What does TCP/IP allow devices to do?"}', '[{"id": "a", "text": {"en": "Display graphics faster"}}, {"id": "b", "text": {"en": "Charge their battery"}}, {"id": "c", "text": {"en": "Communicate using a shared, universal set of rules"}}, {"id": "d", "text": {"en": "Store more data"}}]', 'c', null, 1),
  ('quick_check', 'e8a19e11-9f80-419e-9b7c-95b26fc5d7d0', null, null, '{"en": "What is a \"port\" in networking terms?"}', '[{"id": "a", "text": {"en": "A numbered channel reserved for a specific kind of traffic"}}, {"id": "b", "text": {"en": "A physical USB connector"}}, {"id": "c", "text": {"en": "A type of firewall"}}, {"id": "d", "text": {"en": "A backup device"}}]', 'a', null, 2),
  ('quick_check', 'e8a19e11-9f80-419e-9b7c-95b26fc5d7d0', null, null, '{"en": "Which port is commonly used for secure web traffic (HTTPS)?"}', '[{"id": "a", "text": {"en": "Port 21"}}, {"id": "b", "text": {"en": "Port 25"}}, {"id": "c", "text": {"en": "Port 110"}}, {"id": "d", "text": {"en": "Port 443"}}]', 'd', null, 3),
  ('quick_check', 'e8a19e11-9f80-419e-9b7c-95b26fc5d7d0', null, null, '{"en": "Why do attackers scan for open ports?"}', '[{"id": "a", "text": {"en": "To check the weather"}}, {"id": "b", "text": {"en": "To find an unlocked entry point into a system"}}, {"id": "c", "text": {"en": "To speed up their internet"}}, {"id": "d", "text": {"en": "To update their own software"}}]', 'b', null, 4),
  ('quick_check', 'f8f6b6c1-3f6f-4b1e-8fd0-9e0e1a3b9c8a', null, null, '{"en": "What does DNS do?"}', '[{"id": "a", "text": {"en": "Encrypts your files"}}, {"id": "b", "text": {"en": "Blocks malware"}}, {"id": "c", "text": {"en": "Translates domain names into IP addresses"}}, {"id": "d", "text": {"en": "Speeds up your device"}}]', 'c', null, 1),
  ('quick_check', 'f8f6b6c1-3f6f-4b1e-8fd0-9e0e1a3b9c8a', null, null, '{"en": "In a DNS spoofing attack, an attacker:"}', '[{"id": "a", "text": {"en": "Speeds up DNS lookups"}}, {"id": "b", "text": {"en": "Deletes your browser history"}}, {"id": "c", "text": {"en": "Feeds a DNS server false information to redirect you to a fake site"}}, {"id": "d", "text": {"en": "Encrypts your DNS requests"}}]', 'c', null, 2),
  ('quick_check', 'f8f6b6c1-3f6f-4b1e-8fd0-9e0e1a3b9c8a', null, null, '{"en": "DNS hijacking specifically involves:"}', '[{"id": "a", "text": {"en": "Physically stealing a router"}}, {"id": "b", "text": {"en": "Changing your device''s or router''s DNS settings directly"}}, {"id": "c", "text": {"en": "Creating a stronger password"}}, {"id": "d", "text": {"en": "Installing an antivirus"}}]', 'b', null, 3),
  ('quick_check', 'f8f6b6c1-3f6f-4b1e-8fd0-9e0e1a3b9c8a', null, null, '{"en": "Which is a good practice for DNS security?"}', '[{"id": "a", "text": {"en": "Keeping router firmware updated"}}, {"id": "b", "text": {"en": "Ignoring certificate warnings"}}, {"id": "c", "text": {"en": "Using the oldest DNS provider available"}}, {"id": "d", "text": {"en": "Disabling HTTPS"}}]', 'a', null, 4),
  ('quick_check', 'a1b6a4d3-6b3e-4a4a-8b9d-9f1e2d3c4b5a', null, null, '{"en": "What is network segmentation?"}', '[{"id": "a", "text": {"en": "Splitting a network into separate zones so a breach doesn''t spread everywhere"}}, {"id": "b", "text": {"en": "Deleting parts of a network"}}, {"id": "c", "text": {"en": "Making a network faster"}}, {"id": "d", "text": {"en": "Combining all devices into one shared zone"}}]', 'a', null, 1),
  ('quick_check', 'a1b6a4d3-6b3e-4a4a-8b9d-9f1e2d3c4b5a', null, null, '{"en": "A VLAN is used to:"}', '[{"id": "a", "text": {"en": "Slow down network traffic"}}, {"id": "b", "text": {"en": "Increase Wi-Fi signal strength"}}, {"id": "c", "text": {"en": "Encrypt all files automatically"}}, {"id": "d", "text": {"en": "Create isolated virtual zones within a network"}}]', 'd', null, 2),
  ('quick_check', 'a1b6a4d3-6b3e-4a4a-8b9d-9f1e2d3c4b5a', null, null, '{"en": "Why should guest wifi typically be isolated from internal systems?"}', '[{"id": "a", "text": {"en": "It''s not necessary at all"}}, {"id": "b", "text": {"en": "To make guest wifi faster"}}, {"id": "c", "text": {"en": "So guest devices can''t reach sensitive internal resources"}}, {"id": "d", "text": {"en": "Guests prefer a separate network name only"}}]', 'c', null, 3),
  ('quick_check', 'a1b6a4d3-6b3e-4a4a-8b9d-9f1e2d3c4b5a', null, null, '{"en": "In a \"flat\" network with no segmentation, one compromised device:"}', '[{"id": "a", "text": {"en": "Has no effect on other devices"}}, {"id": "b", "text": {"en": "Can potentially access everything else on the network"}}, {"id": "c", "text": {"en": "Automatically gets isolated"}}, {"id": "d", "text": {"en": "Improves overall security"}}]', 'b', null, 4),
  ('quick_check', 'b2c7b5e4-7c4f-4b5b-9c0e-0a2f3e4d5c6b', null, null, '{"en": "In the shared responsibility model, cloud providers typically secure:"}', '[{"id": "a", "text": {"en": "Your specific data and access settings"}}, {"id": "b", "text": {"en": "Nothing at all"}}, {"id": "c", "text": {"en": "Your personal passwords"}}, {"id": "d", "text": {"en": "The physical infrastructure and underlying hardware"}}]', 'd', null, 1),
  ('quick_check', 'b2c7b5e4-7c4f-4b5b-9c0e-0a2f3e4d5c6b', null, null, '{"en": "Who is responsible for securing your data and access controls in the cloud?"}', '[{"id": "a", "text": {"en": "The cloud provider entirely"}}, {"id": "b", "text": {"en": "You, the customer"}}, {"id": "c", "text": {"en": "No one, it''s automatic"}}, {"id": "d", "text": {"en": "The internet service provider"}}]', 'b', null, 2),
  ('quick_check', 'b2c7b5e4-7c4f-4b5b-9c0e-0a2f3e4d5c6b', null, null, '{"en": "The shared responsibility model is best compared to:"}', '[{"id": "a", "text": {"en": "A hotel where staff clean your room daily"}}, {"id": "b", "text": {"en": "A car with no owner"}}, {"id": "c", "text": {"en": "An apartment where the landlord secures the building but you secure your own door"}}, {"id": "d", "text": {"en": "A library with unrestricted access"}}]', 'c', null, 3),
  ('quick_check', 'b2c7b5e4-7c4f-4b5b-9c0e-0a2f3e4d5c6b', null, null, '{"en": "What''s a common misunderstanding about cloud security?"}', '[{"id": "a", "text": {"en": "That the cloud requires no configuration work from the customer at all"}}, {"id": "b", "text": {"en": "That providers offer no security at all"}}, {"id": "c", "text": {"en": "That data is always fully public"}}, {"id": "d", "text": {"en": "That the cloud is slower than local storage"}}]', 'a', null, 4),
  ('quick_check', 'c3d8c6f5-8d5f-4c6c-8d1f-1b3f4f5e6d7c', null, null, '{"en": "What does IAM stand for?"}', '[{"id": "a", "text": {"en": "Internet Access Monitoring"}}, {"id": "b", "text": {"en": "Identity and Access Management"}}, {"id": "c", "text": {"en": "Internal Application Management"}}, {"id": "d", "text": {"en": "Integrated Antivirus Module"}}]', 'b', null, 1),
  ('quick_check', 'c3d8c6f5-8d5f-4c6c-8d1f-1b3f4f5e6d7c', null, null, '{"en": "The principle of least privilege means:"}', '[{"id": "a", "text": {"en": "Giving users only the access they actually need, nothing more"}}, {"id": "b", "text": {"en": "Giving everyone full admin access"}}, {"id": "c", "text": {"en": "Removing all access from everyone"}}, {"id": "d", "text": {"en": "Sharing one account among all employees"}}]', 'a', null, 2),
  ('quick_check', 'c3d8c6f5-8d5f-4c6c-8d1f-1b3f4f5e6d7c', null, null, '{"en": "Why do many real-world cloud breaches happen?"}', '[{"id": "a", "text": {"en": "Extremely advanced technical exploits only"}}, {"id": "b", "text": {"en": "Weather-related outages"}}, {"id": "c", "text": {"en": "Too much network segmentation"}}, {"id": "d", "text": {"en": "Accounts having far more access than they actually needed"}}]', 'd', null, 3),
  ('quick_check', 'c3d8c6f5-8d5f-4c6c-8d1f-1b3f4f5e6d7c', null, null, '{"en": "When an employee leaves a company, their access should be:"}', '[{"id": "a", "text": {"en": "Left active indefinitely"}}, {"id": "b", "text": {"en": "Shared with a replacement employee"}}, {"id": "c", "text": {"en": "Revoked immediately"}}, {"id": "d", "text": {"en": "Ignored"}}]', 'c', null, 4),
  ('quick_check', 'd4e9d7a6-9e6a-4d7d-9e2a-2c4a5a6f7e8d', null, null, '{"en": "What causes the majority of cloud security incidents?"}', '[{"id": "a", "text": {"en": "Advanced hacking techniques exclusively"}}, {"id": "b", "text": {"en": "Physical theft of servers"}}, {"id": "c", "text": {"en": "Simple misconfigurations, like storage left publicly accessible"}}, {"id": "d", "text": {"en": "Weather events"}}]', 'c', null, 1),
  ('quick_check', 'd4e9d7a6-9e6a-4d7d-9e2a-2c4a5a6f7e8d', null, null, '{"en": "A cloud storage bucket accidentally left \"public\" instead of \"private\" is an example of:"}', '[{"id": "a", "text": {"en": "A strong security practice"}}, {"id": "b", "text": {"en": "A firewall rule"}}, {"id": "c", "text": {"en": "A DDoS attack"}}, {"id": "d", "text": {"en": "A misconfiguration"}}]', 'd', null, 2),
  ('quick_check', 'd4e9d7a6-9e6a-4d7d-9e2a-2c4a5a6f7e8d', null, null, '{"en": "What should be the default assumption for cloud storage access settings?"}', '[{"id": "a", "text": {"en": "Private by default, public only for a clear, deliberate reason"}}, {"id": "b", "text": {"en": "Public by default, private only when needed"}}, {"id": "c", "text": {"en": "It doesn''t matter either way"}}, {"id": "d", "text": {"en": "Always shared with everyone"}}]', 'a', null, 3),
  ('quick_check', 'd4e9d7a6-9e6a-4d7d-9e2a-2c4a5a6f7e8d', null, null, '{"en": "Why are automated configuration-scanning tools useful?"}', '[{"id": "a", "text": {"en": "They replace the need for any security team"}}, {"id": "b", "text": {"en": "Manual review doesn''t scale, so automation helps catch exposed settings"}}, {"id": "c", "text": {"en": "They make cloud storage public automatically"}}, {"id": "d", "text": {"en": "They are only useful for small companies"}}]', 'b', null, 4),
  ('quick_check', 'e5fae8b7-af7b-4e8e-af3b-3d5b6b7a8f9e', null, null, '{"en": "Broken authentication most often results from:"}', '[{"id": "a", "text": {"en": "Using a password manager"}}, {"id": "b", "text": {"en": "Weak points like no lockout after failed attempts or predictable session tokens"}}, {"id": "c", "text": {"en": "Enabling HTTPS"}}, {"id": "d", "text": {"en": "Regularly updating software"}}]', 'b', null, 1),
  ('quick_check', 'e5fae8b7-af7b-4e8e-af3b-3d5b6b7a8f9e', null, null, '{"en": "Insecure deserialization becomes dangerous when an application:"}', '[{"id": "a", "text": {"en": "Encrypts all incoming data"}}, {"id": "b", "text": {"en": "Rejects all external data"}}, {"id": "c", "text": {"en": "Never processes any data"}}, {"id": "d", "text": {"en": "Blindly trusts incoming data without checking it before converting it back to use"}}]', 'd', null, 2),
  ('quick_check', 'e5fae8b7-af7b-4e8e-af3b-3d5b6b7a8f9e', null, null, '{"en": "Security misconfiguration is often described as:"}', '[{"id": "a", "text": {"en": "One of the most common issues, caused by simple unchecked details like default accounts or exposed error messages"}}, {"id": "b", "text": {"en": "A rare, highly sophisticated attack"}}, {"id": "c", "text": {"en": "Something that only affects mobile apps"}}, {"id": "d", "text": {"en": "A type of encryption"}}]', 'a', null, 3),
  ('quick_check', 'e5fae8b7-af7b-4e8e-af3b-3d5b6b7a8f9e', null, null, '{"en": "Why does the OWASP Top 10 matter to a non-developer?"}', '[{"id": "a", "text": {"en": "It''s only relevant to programmers"}}, {"id": "b", "text": {"en": "It has no practical use"}}, {"id": "c", "text": {"en": "It tells you exactly what a security-conscious team should already be checking"}}, {"id": "d", "text": {"en": "It''s a list of banned websites"}}]', 'c', null, 4),
  ('quick_check', 'f6a0f9c8-b08c-4f9f-b04c-4e6c7c8b9a0f', null, null, '{"en": "CSRF tricks your browser into:"}', '[{"id": "a", "text": {"en": "Encrypting your data"}}, {"id": "b", "text": {"en": "Blocking a website entirely"}}, {"id": "c", "text": {"en": "Sending an unintended request to a site you''re already logged into"}}, {"id": "d", "text": {"en": "Deleting your session token"}}]', 'c', null, 1),
  ('quick_check', 'f6a0f9c8-b08c-4f9f-b04c-4e6c7c8b9a0f', null, null, '{"en": "A session token is:"}', '[{"id": "a", "text": {"en": "Proof that you''re authenticated, attached automatically to your requests to that site"}}, {"id": "b", "text": {"en": "A type of malware"}}, {"id": "c", "text": {"en": "A physical security key"}}, {"id": "d", "text": {"en": "The same as your password"}}]', 'a', null, 2),
  ('quick_check', 'f6a0f9c8-b08c-4f9f-b04c-4e6c7c8b9a0f', null, null, '{"en": "SameSite cookies help prevent CSRF by:"}', '[{"id": "a", "text": {"en": "Encrypting all cookies permanently"}}, {"id": "b", "text": {"en": "Deleting cookies after every session"}}, {"id": "c", "text": {"en": "Making cookies visible to every website"}}, {"id": "d", "text": {"en": "Stopping cookies from being sent with requests that originate from a different site"}}]', 'd', null, 3),
  ('quick_check', 'f6a0f9c8-b08c-4f9f-b04c-4e6c7c8b9a0f', null, null, '{"en": "What''s one practical thing you can do to reduce CSRF risk?"}', '[{"id": "a", "text": {"en": "Never log into any account ever"}}, {"id": "b", "text": {"en": "Log out of sensitive accounts when you''re done rather than just closing the tab"}}, {"id": "c", "text": {"en": "Disable your browser entirely"}}, {"id": "d", "text": {"en": "Use the same session forever"}}]', 'b', null, 4),
  ('quick_check', 'a7b1a0d9-c19d-4a0a-c15d-5f7d8d9c0b1a', null, null, '{"en": "The Secure Development Lifecycle treats security as:"}', '[{"id": "a", "text": {"en": "A final checkbox at the very end"}}, {"id": "b", "text": {"en": "Something only testers need to worry about"}}, {"id": "c", "text": {"en": "Unnecessary for small projects"}}, {"id": "d", "text": {"en": "A thread running through every stage of development, not just a final step"}}]', 'd', null, 1),
  ('quick_check', 'a7b1a0d9-c19d-4a0a-c15d-5f7d8d9c0b1a', null, null, '{"en": "During the \"development\" stage, secure coding standards include:"}', '[{"id": "a", "text": {"en": "Hardcoding passwords directly into the code for convenience"}}, {"id": "b", "text": {"en": "Validating input and never trusting data from the user"}}, {"id": "c", "text": {"en": "Skipping input validation to save time"}}, {"id": "d", "text": {"en": "Ignoring known vulnerabilities"}}]', 'b', null, 2),
  ('quick_check', 'a7b1a0d9-c19d-4a0a-c15d-5f7d8d9c0b1a', null, null, '{"en": "Code review is valuable because:"}', '[{"id": "a", "text": {"en": "It slows down releases unnecessarily"}}, {"id": "b", "text": {"en": "It''s only useful for junior developers"}}, {"id": "c", "text": {"en": "A second set of eyes catches what the original developer missed"}}, {"id": "d", "text": {"en": "It replaces the need for testing entirely"}}]', 'c', null, 3),
  ('quick_check', 'a7b1a0d9-c19d-4a0a-c15d-5f7d8d9c0b1a', null, null, '{"en": "Why is it generally cheaper to build security in from the start rather than fix it later?"}', '[{"id": "a", "text": {"en": "Fixing a security flaw after launch costs dramatically more than catching it during design"}}, {"id": "b", "text": {"en": "It isn''t actually cheaper either way"}}, {"id": "c", "text": {"en": "Security fixes are always free"}}, {"id": "d", "text": {"en": "Early security work is always more expensive"}}]', 'a', null, 4),
  ('quick_check', 'b8c2b1e0-d2ae-4b1b-d26e-6a8e9e0d1c2b', null, null, '{"en": "WEP is considered:"}', '[{"id": "a", "text": {"en": "The strongest current wifi standard"}}, {"id": "b", "text": {"en": "Impossible to crack"}}, {"id": "c", "text": {"en": "Badly broken, crackable by freely available tools in minutes"}}, {"id": "d", "text": {"en": "A type of firewall"}}]', 'c', null, 1),
  ('quick_check', 'b8c2b1e0-d2ae-4b1b-d26e-6a8e9e0d1c2b', null, null, '{"en": "WPA3 improves on previous standards by:"}', '[{"id": "a", "text": {"en": "Adding stronger protection even when a user has a weak password"}}, {"id": "b", "text": {"en": "Removing encryption entirely"}}, {"id": "c", "text": {"en": "Only working on mobile devices"}}, {"id": "d", "text": {"en": "Slowing down network speed intentionally"}}]', 'a', null, 2),
  ('quick_check', 'b8c2b1e0-d2ae-4b1b-d26e-6a8e9e0d1c2b', null, null, '{"en": "KRACK is a known vulnerability affecting:"}', '[{"id": "a", "text": {"en": "WEP only"}}, {"id": "b", "text": {"en": "Wired ethernet cables"}}, {"id": "c", "text": {"en": "Physical router theft"}}, {"id": "d", "text": {"en": "WPA2"}}]', 'd', null, 3),
  ('quick_check', 'b8c2b1e0-d2ae-4b1b-d26e-6a8e9e0d1c2b', null, null, '{"en": "What''s a practical takeaway from this lesson?"}', '[{"id": "a", "text": {"en": "All wifi standards are equally secure"}}, {"id": "b", "text": {"en": "Check your router settings and upgrade away from WEP or plain WPA if you find them"}}, {"id": "c", "text": {"en": "Wifi security doesn''t matter at home"}}, {"id": "d", "text": {"en": "Older routers are always safer"}}]', 'b', null, 4),
  ('quick_check', 'c9d3c2f1-e3bf-4c2c-e37f-7b9f0f1e2d3c', null, null, '{"en": "Bluejacking involves:"}', '[{"id": "a", "text": {"en": "Stealing files from a device"}}, {"id": "b", "text": {"en": "Sending unsolicited messages to nearby discoverable Bluetooth devices"}}, {"id": "c", "text": {"en": "Physically damaging a device"}}, {"id": "d", "text": {"en": "Encrypting a device''s data"}}]', 'b', null, 1),
  ('quick_check', 'c9d3c2f1-e3bf-4c2c-e37f-7b9f0f1e2d3c', null, null, '{"en": "Bluesnarfing is dangerous because it:"}', '[{"id": "a", "text": {"en": "Only affects old devices"}}, {"id": "b", "text": {"en": "Simply sends annoying messages"}}, {"id": "c", "text": {"en": "Requires physical access to the device"}}, {"id": "d", "text": {"en": "Lets an attacker access data like contacts and files without permission"}}]', 'd', null, 2),
  ('quick_check', 'c9d3c2f1-e3bf-4c2c-e37f-7b9f0f1e2d3c', null, null, '{"en": "A practical way to reduce Bluetooth risk is to:"}', '[{"id": "a", "text": {"en": "Turn Bluetooth off when not actively using it"}}, {"id": "b", "text": {"en": "Always leave Bluetooth discoverable"}}, {"id": "c", "text": {"en": "Accept every pairing request automatically"}}, {"id": "d", "text": {"en": "Never update your device''s software"}}]', 'a', null, 3),
  ('quick_check', 'c9d3c2f1-e3bf-4c2c-e37f-7b9f0f1e2d3c', null, null, '{"en": "BlueBorne, discovered in 2017, was notable because it:"}', '[{"id": "a", "text": {"en": "Only worked on desktop computers"}}, {"id": "b", "text": {"en": "Required the victim to click a link"}}, {"id": "c", "text": {"en": "Could let an attacker take over a device without any pairing or click at all"}}, {"id": "d", "text": {"en": "Was completely harmless"}}]', 'c', null, 4),
  ('quick_check', 'd0e4d3a2-f4c0-4d3d-f480-8c0a1a2f3e4d', null, null, '{"en": "A flashlight app requesting access to your contacts is:"}', '[{"id": "a", "text": {"en": "A red flag, since it has no real technical need for that access"}}, {"id": "b", "text": {"en": "Completely normal and necessary"}}, {"id": "c", "text": {"en": "Required by app stores"}}, {"id": "d", "text": {"en": "A sign of strong security"}}]', 'a', null, 1),
  ('quick_check', 'd0e4d3a2-f4c0-4d3d-f480-8c0a1a2f3e4d', null, null, '{"en": "Every permission you grant an app is:"}', '[{"id": "a", "text": {"en": "Automatically revoked after a week"}}, {"id": "b", "text": {"en": "Irrelevant to your privacy"}}, {"id": "c", "text": {"en": "A potential channel for abuse if misused"}}, {"id": "d", "text": {"en": "Required for the app to even install"}}]', 'c', null, 2),
  ('quick_check', 'd0e4d3a2-f4c0-4d3d-f480-8c0a1a2f3e4d', null, null, '{"en": "Mobile malware often gets distributed by:"}', '[{"id": "a", "text": {"en": "Only official, well-reviewed app store listings"}}, {"id": "b", "text": {"en": "Disguising itself as a legitimate app, sometimes outside official app stores"}}, {"id": "c", "text": {"en": "Physical USB connection exclusively"}}, {"id": "d", "text": {"en": "Government agencies"}}]', 'b', null, 3),
  ('quick_check', 'd0e4d3a2-f4c0-4d3d-f480-8c0a1a2f3e4d', null, null, '{"en": "A good practical habit for mobile app permissions is to:"}', '[{"id": "a", "text": {"en": "Grant every permission an app requests immediately"}}, {"id": "b", "text": {"en": "Never install any apps at all"}}, {"id": "c", "text": {"en": "Ignore app reviews entirely"}}, {"id": "d", "text": {"en": "Regularly review and revoke permissions you no longer think are necessary"}}]', 'd', null, 4),
  ('quick_check', 'e1f5e4b3-a5d1-4e4e-a591-9d1b2b3a4f5e', null, null, '{"en": "A digital certificate is issued by:"}', '[{"id": "a", "text": {"en": "The website owner alone"}}, {"id": "b", "text": {"en": "A trusted third party called a Certificate Authority"}}, {"id": "c", "text": {"en": "Your internet service provider"}}, {"id": "d", "text": {"en": "Your antivirus software"}}]', 'b', null, 1),
  ('quick_check', 'e1f5e4b3-a5d1-4e4e-a591-9d1b2b3a4f5e', null, null, '{"en": "A digital signature proves:"}', '[{"id": "a", "text": {"en": "Only that a file is small"}}, {"id": "b", "text": {"en": "Nothing useful"}}, {"id": "c", "text": {"en": "That a website loads quickly"}}, {"id": "d", "text": {"en": "That content came from the claimed source and hasn''t been tampered with"}}]', 'd', null, 2),
  ('quick_check', 'e1f5e4b3-a5d1-4e4e-a591-9d1b2b3a4f5e', null, null, '{"en": "A digital signature is created using:"}', '[{"id": "a", "text": {"en": "The signer''s private key"}}, {"id": "b", "text": {"en": "The signer''s public key"}}, {"id": "c", "text": {"en": "A shared password"}}, {"id": "d", "text": {"en": "A firewall rule"}}]', 'a', null, 3),
  ('quick_check', 'e1f5e4b3-a5d1-4e4e-a591-9d1b2b3a4f5e', null, null, '{"en": "The padlock icon in your browser mainly confirms:"}', '[{"id": "a", "text": {"en": "The site''s content is completely trustworthy"}}, {"id": "b", "text": {"en": "The site loads faster than others"}}, {"id": "c", "text": {"en": "You''re actually communicating with the domain you think you are"}}, {"id": "d", "text": {"en": "The site has no ads"}}]', 'c', null, 4),
  ('quick_check', 'f2a6f5c4-b6e2-4f5f-b6a2-0e2c3c4b5a6f', null, null, '{"en": "PKI is best described as:"}', '[{"id": "a", "text": {"en": "A single company"}}, {"id": "b", "text": {"en": "A type of firewall"}}, {"id": "c", "text": {"en": "The entire framework of trust that makes certificate-based verification work"}}, {"id": "d", "text": {"en": "A password manager"}}]', 'c', null, 1),
  ('quick_check', 'f2a6f5c4-b6e2-4f5f-b6a2-0e2c3c4b5a6f', null, null, '{"en": "The \"chain of trust\" ultimately traces back to:"}', '[{"id": "a", "text": {"en": "A trusted root Certificate Authority built into your browser"}}, {"id": "b", "text": {"en": "Your internet service provider"}}, {"id": "c", "text": {"en": "The website itself"}}, {"id": "d", "text": {"en": "A random server"}}]', 'a', null, 2),
  ('quick_check', 'f2a6f5c4-b6e2-4f5f-b6a2-0e2c3c4b5a6f', null, null, '{"en": "Root CAs can vouch for:"}', '[{"id": "a", "text": {"en": "Nothing else"}}, {"id": "b", "text": {"en": "Only themselves"}}, {"id": "c", "text": {"en": "Your personal devices"}}, {"id": "d", "text": {"en": "Intermediate CAs, which then issue certificates to websites"}}]', 'd', null, 3),
  ('quick_check', 'f2a6f5c4-b6e2-4f5f-b6a2-0e2c3c4b5a6f', null, null, '{"en": "When a certificate is improperly issued or a CA is compromised, browsers can:"}', '[{"id": "a", "text": {"en": "Ignore the problem entirely"}}, {"id": "b", "text": {"en": "Revoke trust in specific certificates"}}, {"id": "c", "text": {"en": "Automatically fix the certificate"}}, {"id": "d", "text": {"en": "Shut down the internet"}}]', 'b', null, 4),
  ('quick_check', 'a3b7a6d5-c7f3-4a6a-c7b3-1f3d4d5c6b7a', null, null, '{"en": "The TLS handshake happens:"}', '[{"id": "a", "text": {"en": "Only once per year"}}, {"id": "b", "text": {"en": "Only when a website has an error"}}, {"id": "c", "text": {"en": "Manually, initiated by the user"}}, {"id": "d", "text": {"en": "Automatically, every time you connect to an HTTPS site"}}]', 'd', null, 1),
  ('quick_check', 'a3b7a6d5-c7f3-4a6a-c7b3-1f3d4d5c6b7a', null, null, '{"en": "During the handshake, the server proves its identity by presenting:"}', '[{"id": "a", "text": {"en": "A password"}}, {"id": "b", "text": {"en": "Its digital certificate"}}, {"id": "c", "text": {"en": "Its IP address only"}}, {"id": "d", "text": {"en": "A firewall rule"}}]', 'b', null, 2),
  ('quick_check', 'a3b7a6d5-c7f3-4a6a-c7b3-1f3d4d5c6b7a', null, null, '{"en": "The session key established during the handshake is used for:"}', '[{"id": "a", "text": {"en": "Storing your password"}}, {"id": "b", "text": {"en": "Displaying the website''s logo"}}, {"id": "c", "text": {"en": "Symmetric encryption of the actual conversation going forward"}}, {"id": "d", "text": {"en": "Nothing important"}}]', 'c', null, 3),
  ('quick_check', 'a3b7a6d5-c7f3-4a6a-c7b3-1f3d4d5c6b7a', null, null, '{"en": "Why is symmetric encryption used for the bulk of the actual data after the handshake?"}', '[{"id": "a", "text": {"en": "It''s faster and more efficient than asymmetric encryption"}}, {"id": "b", "text": {"en": "It''s less secure but looks better"}}, {"id": "c", "text": {"en": "Asymmetric encryption doesn''t exist"}}, {"id": "d", "text": {"en": "Symmetric encryption is illegal to use for large data"}}]', 'a', null, 4),
  ('quick_check', 'b4c8b7e6-d8a4-4b7b-d8c4-2a4e5e6d7c8b', null, null, '{"en": "Passive reconnaissance involves:"}', '[{"id": "a", "text": {"en": "Directly hacking into a system"}}, {"id": "b", "text": {"en": "Sending malware to the target"}}, {"id": "c", "text": {"en": "Gathering information without directly interacting with the target''s systems"}}, {"id": "d", "text": {"en": "Only reading company financial reports"}}]', 'c', null, 1),
  ('quick_check', 'b4c8b7e6-d8a4-4b7b-d8c4-2a4e5e6d7c8b', null, null, '{"en": "Active reconnaissance, unlike passive, involves:"}', '[{"id": "a", "text": {"en": "Directly interacting with the target''s systems"}}, {"id": "b", "text": {"en": "No interaction with anything at all"}}, {"id": "c", "text": {"en": "Only reading public news articles"}}, {"id": "d", "text": {"en": "Skipping straight to exploitation"}}]', 'a', null, 2),
  ('quick_check', 'b4c8b7e6-d8a4-4b7b-d8c4-2a4e5e6d7c8b', null, null, '{"en": "Scanning, following reconnaissance, is used to:"}', '[{"id": "a", "text": {"en": "Delete data"}}, {"id": "b", "text": {"en": "Send phishing emails"}}, {"id": "c", "text": {"en": "Encrypt files"}}, {"id": "d", "text": {"en": "Systematically probe discovered systems for known vulnerabilities and weak points"}}]', 'd', null, 3),
  ('quick_check', 'b4c8b7e6-d8a4-4b7b-d8c4-2a4e5e6d7c8b', null, null, '{"en": "Why do skilled testers spend significant time on reconnaissance?"}', '[{"id": "a", "text": {"en": "It''s required by law"}}, {"id": "b", "text": {"en": "Attacking blind wastes time and increases the risk of getting caught before finding anything useful"}}, {"id": "c", "text": {"en": "It has no real benefit"}}, {"id": "d", "text": {"en": "It''s the fastest part of the process"}}]', 'b', null, 4),
  ('quick_check', 'c5d9c8f7-e9b5-4c8c-e9d5-3b5f6f7e8d9c', null, null, '{"en": "An exploit is:"}', '[{"id": "a", "text": {"en": "A type of firewall"}}, {"id": "b", "text": {"en": "A piece of code or technique that takes advantage of a specific vulnerability"}}, {"id": "c", "text": {"en": "A password policy"}}, {"id": "d", "text": {"en": "A backup strategy"}}]', 'b', null, 1),
  ('quick_check', 'c5d9c8f7-e9b5-4c8c-e9d5-3b5f6f7e8d9c', null, null, '{"en": "Privilege escalation means:"}', '[{"id": "a", "text": {"en": "Deleting all user accounts"}}, {"id": "b", "text": {"en": "Reducing everyone''s access to nothing"}}, {"id": "c", "text": {"en": "Installing new software"}}, {"id": "d", "text": {"en": "Turning limited access into broader access"}}]', 'd', null, 2),
  ('quick_check', 'c5d9c8f7-e9b5-4c8c-e9d5-3b5f6f7e8d9c', null, null, '{"en": "Post-exploitation focuses on:"}', '[{"id": "a", "text": {"en": "Understanding what an attacker could actually do with the access gained"}}, {"id": "b", "text": {"en": "Immediately ending the entire test"}}, {"id": "c", "text": {"en": "Ignoring the access once it''s gained"}}, {"id": "d", "text": {"en": "Only checking the time of day"}}]', 'a', null, 3),
  ('quick_check', 'c5d9c8f7-e9b5-4c8c-e9d5-3b5f6f7e8d9c', null, null, '{"en": "Why do penetration testers actually exploit vulnerabilities rather than just reporting them theoretically?"}', '[{"id": "a", "text": {"en": "It''s required for fun"}}, {"id": "b", "text": {"en": "Theoretical vulnerabilities are always ignored completely regardless"}}, {"id": "c", "text": {"en": "Demonstrating a vulnerability is real and exploitable often drives organizations to actually fix it"}}, {"id": "d", "text": {"en": "There''s no real reason"}}]', 'c', null, 4),
  ('quick_check', 'd6eada08-fac6-4d9d-fae6-4c6a7a8f9e0d', null, null, '{"en": "The most valuable deliverable of a penetration test is often:"}', '[{"id": "a", "text": {"en": "The report"}}, {"id": "b", "text": {"en": "The exploit code itself"}}, {"id": "c", "text": {"en": "A list of every employee''s name"}}, {"id": "d", "text": {"en": "A new firewall"}}]', 'a', null, 1),
  ('quick_check', 'd6eada08-fac6-4d9d-fae6-4c6a7a8f9e0d', null, null, '{"en": "An executive summary in a pentest report is meant for:"}', '[{"id": "a", "text": {"en": "Only technical staff"}}, {"id": "b", "text": {"en": "No one; it''s optional filler"}}, {"id": "c", "text": {"en": "Leadership, focused on business risk rather than technical detail"}}, {"id": "d", "text": {"en": "Marketing purposes only"}}]', 'c', null, 2),
  ('quick_check', 'd6eada08-fac6-4d9d-fae6-4c6a7a8f9e0d', null, null, '{"en": "Risk ratings in a report help by:"}', '[{"id": "a", "text": {"en": "Making every issue seem equally urgent"}}, {"id": "b", "text": {"en": "Prioritizing issues by actual severity and likelihood"}}, {"id": "c", "text": {"en": "Hiding the most dangerous findings"}}, {"id": "d", "text": {"en": "Removing the need for remediation steps"}}]', 'b', null, 3),
  ('quick_check', 'd6eada08-fac6-4d9d-fae6-4c6a7a8f9e0d', null, null, '{"en": "Remediation verification exists to:"}', '[{"id": "a", "text": {"en": "Skip confirming whether a fix actually worked"}}, {"id": "b", "text": {"en": "Create unnecessary extra work"}}, {"id": "c", "text": {"en": "Replace the need for an initial report"}}, {"id": "d", "text": {"en": "Confirm a vulnerability is actually resolved, not just reported as fixed"}}]', 'd', null, 4),
  ('quick_check', 'e7fbeb19-0bd7-4e0e-0bf7-5d7b8b9a0f1e', null, null, '{"en": "Digital forensics is best described as:"}', '[{"id": "a", "text": {"en": "Randomly guessing what happened"}}, {"id": "b", "text": {"en": "Deleting compromised systems immediately"}}, {"id": "c", "text": {"en": "A casual review with no documentation"}}, {"id": "d", "text": {"en": "Properly collecting, preserving, and analyzing digital evidence after an incident"}}]', 'd', null, 1),
  ('quick_check', 'e7fbeb19-0bd7-4e0e-0bf7-5d7b8b9a0f1e', null, null, '{"en": "Why shouldn''t you immediately power off a compromised machine?"}', '[{"id": "a", "text": {"en": "Doing so can wipe volatile data in memory that might hold crucial evidence"}}, {"id": "b", "text": {"en": "It''s against the law everywhere"}}, {"id": "c", "text": {"en": "It makes the investigation faster"}}, {"id": "d", "text": {"en": "It has no real downside"}}]', 'a', null, 2),
  ('quick_check', 'e7fbeb19-0bd7-4e0e-0bf7-5d7b8b9a0f1e', null, null, '{"en": "A forensic image is:"}', '[{"id": "a", "text": {"en": "A photograph of the server room"}}, {"id": "b", "text": {"en": "A marketing screenshot"}}, {"id": "c", "text": {"en": "An exact, bit-for-bit copy of the affected system"}}, {"id": "d", "text": {"en": "A summary report only"}}]', 'c', null, 3),
  ('quick_check', 'e7fbeb19-0bd7-4e0e-0bf7-5d7b8b9a0f1e', null, null, '{"en": "Why does rigorous documentation matter during first response?"}', '[{"id": "a", "text": {"en": "It''s optional and rarely useful"}}, {"id": "b", "text": {"en": "Sloppy response can destroy the very evidence needed to understand what happened"}}, {"id": "c", "text": {"en": "It slows down recovery unnecessarily"}}, {"id": "d", "text": {"en": "It''s only relevant for large companies"}}]', 'b', null, 4),
  ('quick_check', 'f80fbc2a-1ce8-4f1f-1c08-6e8c9c0b1a2f', null, null, '{"en": "Chain of custody is:"}', '[{"id": "a", "text": {"en": "A type of firewall"}}, {"id": "b", "text": {"en": "A documented, unbroken record of who handled evidence, when, and what they did with it"}}, {"id": "c", "text": {"en": "A backup strategy"}}, {"id": "d", "text": {"en": "An encryption method"}}]', 'b', null, 1),
  ('quick_check', 'f80fbc2a-1ce8-4f1f-1c08-6e8c9c0b1a2f', null, null, '{"en": "Why does chain of custody matter so much?"}', '[{"id": "a", "text": {"en": "It''s just a formality with no real purpose"}}, {"id": "b", "text": {"en": "It makes investigations slower for no reason"}}, {"id": "c", "text": {"en": "It''s only relevant for physical evidence"}}, {"id": "d", "text": {"en": "Without it, evidence could be argued as tampered with, altered, or mishandled"}}]', 'd', null, 2),
  ('quick_check', 'f80fbc2a-1ce8-4f1f-1c08-6e8c9c0b1a2f', null, null, '{"en": "Which of these can break a chain of custody?"}', '[{"id": "a", "text": {"en": "Gaps in documentation when evidence changes hands"}}, {"id": "b", "text": {"en": "Using a verified copy for analysis"}}, {"id": "c", "text": {"en": "Properly securing storage"}}, {"id": "d", "text": {"en": "Logging every handoff"}}]', 'a', null, 3),
  ('quick_check', 'f80fbc2a-1ce8-4f1f-1c08-6e8c9c0b1a2f', null, null, '{"en": "A practical mindset for handling digital evidence is to:"}', '[{"id": "a", "text": {"en": "Assume no one will ever question it"}}, {"id": "b", "text": {"en": "Skip documentation to save time"}}, {"id": "c", "text": {"en": "Treat every piece of evidence as if its authenticity will eventually be challenged"}}, {"id": "d", "text": {"en": "Only document evidence that seems important"}}]', 'c', null, 4),
  ('quick_check', '091fcd3b-2df9-4020-2d19-7f9d0d1c2b3a', null, null, '{"en": "Logs are:"}', '[{"id": "a", "text": {"en": "Records that applications and systems automatically keep of events"}}, {"id": "b", "text": {"en": "A type of encryption"}}, {"id": "c", "text": {"en": "Physical evidence only"}}, {"id": "d", "text": {"en": "Something that''s always immediately deleted"}}]', 'a', null, 1),
  ('quick_check', '091fcd3b-2df9-4020-2d19-7f9d0d1c2b3a', null, null, '{"en": "Metadata is best described as:"}', '[{"id": "a", "text": {"en": "The actual content of a file"}}, {"id": "b", "text": {"en": "A type of malware"}}, {"id": "c", "text": {"en": "Data about data, like a file''s creation date or location"}}, {"id": "d", "text": {"en": "A firewall setting"}}]', 'c', null, 2),
  ('quick_check', '091fcd3b-2df9-4020-2d19-7f9d0d1c2b3a', null, null, '{"en": "Artifacts, in a forensic sense, refers to:"}', '[{"id": "a", "text": {"en": "Only physical objects found at a crime scene"}}, {"id": "b", "text": {"en": "Any trace left behind by activity on a system"}}, {"id": "c", "text": {"en": "Encrypted files exclusively"}}, {"id": "d", "text": {"en": "A type of backup"}}]', 'b', null, 3),
  ('quick_check', '091fcd3b-2df9-4020-2d19-7f9d0d1c2b3a', null, null, '{"en": "Why is \"deleted\" often misleading in digital forensics?"}', '[{"id": "a", "text": {"en": "Deleted files are always instantly and completely gone"}}, {"id": "b", "text": {"en": "Deletion has no relevance to forensics"}}, {"id": "c", "text": {"en": "Files can never actually be deleted at all"}}, {"id": "d", "text": {"en": "Deleted actions often still leave traces (artifacts) behind"}}]', 'd', null, 4),
  ('quick_check', '1a20de4c-3e0a-4131-3e2a-8a0e1e2d3c4b', null, null, '{"en": "A SOC is:"}', '[{"id": "a", "text": {"en": "A type of firewall"}}, {"id": "b", "text": {"en": "A single automated tool"}}, {"id": "c", "text": {"en": "A physical building only"}}, {"id": "d", "text": {"en": "The team responsible for continuously monitoring, detecting, and responding to security threats"}}]', 'd', null, 1),
  ('quick_check', '1a20de4c-3e0a-4131-3e2a-8a0e1e2d3c4b', null, null, '{"en": "Tier 1 analysts primarily:"}', '[{"id": "a", "text": {"en": "Handle only the most complex, proactive threat hunting"}}, {"id": "b", "text": {"en": "Triage incoming alerts and filter out false positives"}}, {"id": "c", "text": {"en": "Never interact with alerts at all"}}, {"id": "d", "text": {"en": "Manage the company''s finances"}}]', 'b', null, 2),
  ('quick_check', '1a20de4c-3e0a-4131-3e2a-8a0e1e2d3c4b', null, null, '{"en": "Tier 3 analysts (threat hunters) often:"}', '[{"id": "a", "text": {"en": "Proactively search for threats that haven''t triggered any alert at all"}}, {"id": "b", "text": {"en": "Only handle basic password resets"}}, {"id": "c", "text": {"en": "Ignore complex cases entirely"}}, {"id": "d", "text": {"en": "Work exclusively on marketing tasks"}}]', 'a', null, 3),
  ('quick_check', '1a20de4c-3e0a-4131-3e2a-8a0e1e2d3c4b', null, null, '{"en": "Why does a SOC typically operate around the clock?"}', '[{"id": "a", "text": {"en": "It''s required for no real reason"}}, {"id": "b", "text": {"en": "Attackers only work business hours"}}, {"id": "c", "text": {"en": "Attackers don''t work business hours, and detection speed matters significantly"}}, {"id": "d", "text": {"en": "It has nothing to do with damage limitation"}}]', 'c', null, 4),
  ('quick_check', '2b31ef5d-4f1b-4242-4f3b-9b1f2f3e4d5c', null, null, '{"en": "A SIEM system primarily:"}', '[{"id": "a", "text": {"en": "Physically blocks network traffic"}}, {"id": "b", "text": {"en": "Only stores backups"}}, {"id": "c", "text": {"en": "Centralizes logs from across an environment and correlates them to surface what matters"}}, {"id": "d", "text": {"en": "Replaces the need for any human analyst entirely"}}]', 'c', null, 1),
  ('quick_check', '2b31ef5d-4f1b-4242-4f3b-9b1f2f3e4d5c', null, null, '{"en": "Correlation in a SIEM is valuable because:"}', '[{"id": "a", "text": {"en": "A single log entry always tells the complete story"}}, {"id": "b", "text": {"en": "It has no real practical use"}}, {"id": "c", "text": {"en": "It only works for very small companies"}}, {"id": "d", "text": {"en": "Combining multiple related events reveals patterns no individual log entry shows alone"}}]', 'd', null, 2),
  ('quick_check', '2b31ef5d-4f1b-4242-4f3b-9b1f2f3e4d5c', null, null, '{"en": "A common challenge with SIEM tools is:"}', '[{"id": "a", "text": {"en": "They never generate false positives"}}, {"id": "b", "text": {"en": "Poorly tuned rules can flood analysts with false positives"}}, {"id": "c", "text": {"en": "They require no configuration whatsoever"}}, {"id": "d", "text": {"en": "They only work once, with no ongoing tuning needed"}}]', 'b', null, 3),
  ('quick_check', '2b31ef5d-4f1b-4242-4f3b-9b1f2f3e4d5c', null, null, '{"en": "A SOC''s effectiveness depends heavily on:"}', '[{"id": "a", "text": {"en": "How well its SIEM is configured, not just the tool''s existence"}}, {"id": "b", "text": {"en": "Having the largest number of analysts possible"}}, {"id": "c", "text": {"en": "Ignoring alerts entirely"}}, {"id": "d", "text": {"en": "Ignoring log data"}}]', 'a', null, 4),
  ('quick_check', '3c42f06e-5020-4353-5040-0c203031e4d6', null, null, '{"en": "Threat intelligence is:"}', '[{"id": "a", "text": {"en": "Guessing randomly about future attacks"}}, {"id": "b", "text": {"en": "Gathering, analyzing, and applying knowledge about active threats and attacker techniques"}}, {"id": "c", "text": {"en": "Only relevant to government agencies"}}, {"id": "d", "text": {"en": "A type of firewall"}}]', 'b', null, 1),
  ('quick_check', '3c42f06e-5020-4353-5040-0c203031e4d6', null, null, '{"en": "MITRE ATT&CK is best described as:"}', '[{"id": "a", "text": {"en": "A structured knowledge base of real-world attacker tactics and techniques"}}, {"id": "b", "text": {"en": "A single antivirus product"}}, {"id": "c", "text": {"en": "A type of encryption standard"}}, {"id": "d", "text": {"en": "A physical security device"}}]', 'a', null, 2),
  ('quick_check', '3c42f06e-5020-4353-5040-0c203031e4d6', null, null, '{"en": "Why is a shared, structured vocabulary like ATT&CK helpful for defenders?"}', '[{"id": "a", "text": {"en": "It has no practical benefit"}}, {"id": "b", "text": {"en": "It slows down investigations unnecessarily"}}, {"id": "c", "text": {"en": "It only applies to one specific company"}}, {"id": "d", "text": {"en": "It lets teams reference exact techniques and compare them against known threat groups"}}]', 'd', null, 3),
  ('quick_check', '3c42f06e-5020-4353-5040-0c203031e4d6', null, null, '{"en": "SOCs can use ATT&CK to:"}', '[{"id": "a", "text": {"en": "Ignore detection gaps entirely"}}, {"id": "b", "text": {"en": "Randomly select which alerts to investigate"}}, {"id": "c", "text": {"en": "Map detection coverage and identify blind spots in what techniques would go undetected"}}, {"id": "d", "text": {"en": "Replace the need for a SIEM entirely"}}]', 'c', null, 4),
  ('quick_check', '4d53013f-6131-4464-6151-1d3141425e6a', null, null, '{"en": "A security policy is:"}', '[{"id": "a", "text": {"en": "A formal document defining an organization''s security rules and expectations"}}, {"id": "b", "text": {"en": "An optional suggestion with no real weight"}}, {"id": "c", "text": {"en": "Only relevant to IT staff"}}, {"id": "d", "text": {"en": "A type of firewall"}}]', 'a', null, 1),
  ('quick_check', '4d53013f-6131-4464-6151-1d3141425e6a', null, null, '{"en": "An Acceptable Use Policy defines:"}', '[{"id": "a", "text": {"en": "Password complexity rules only"}}, {"id": "b", "text": {"en": "Risk ratings for vulnerabilities"}}, {"id": "c", "text": {"en": "What employees can and can''t do with company systems and data"}}, {"id": "d", "text": {"en": "Encryption standards only"}}]', 'c', null, 2),
  ('quick_check', '4d53013f-6131-4464-6151-1d3141425e6a', null, null, '{"en": "Why does a written policy matter more than assuming \"everyone knows the right thing\"?"}', '[{"id": "a", "text": {"en": "It doesn''t actually matter"}}, {"id": "b", "text": {"en": "Written policies are always ignored anyway"}}, {"id": "c", "text": {"en": "It only matters for very small teams"}}, {"id": "d", "text": {"en": "It removes ambiguity, especially as an organization grows"}}]', 'd', null, 3),
  ('quick_check', '4d53013f-6131-4464-6151-1d3141425e6a', null, null, '{"en": "A policy that exists only on paper, never enforced or trained on:"}', '[{"id": "a", "text": {"en": "Is just as effective as an enforced one"}}, {"id": "b", "text": {"en": "Does almost nothing in practice"}}, {"id": "c", "text": {"en": "Is illegal"}}, {"id": "d", "text": {"en": "Replaces the need for technical controls"}}]', 'b', null, 4),
  ('quick_check', '5e64124f-7242-4575-7262-2e4252536f7b', null, null, '{"en": "Risk is typically thought of as:"}', '[{"id": "a", "text": {"en": "Impact alone"}}, {"id": "b", "text": {"en": "Likelihood alone"}}, {"id": "c", "text": {"en": "A random guess"}}, {"id": "d", "text": {"en": "Likelihood multiplied by impact"}}]', 'd', null, 1),
  ('quick_check', '5e64124f-7242-4575-7262-2e4252536f7b', null, null, '{"en": "The first step in a typical risk assessment is:"}', '[{"id": "a", "text": {"en": "Deciding on treatment"}}, {"id": "b", "text": {"en": "Identifying assets that need protecting"}}, {"id": "c", "text": {"en": "Calculating final risk scores"}}, {"id": "d", "text": {"en": "Buying insurance"}}]', 'b', null, 2),
  ('quick_check', '5e64124f-7242-4575-7262-2e4252536f7b', null, null, '{"en": "\"Accepting\" a risk means:"}', '[{"id": "a", "text": {"en": "Formally acknowledging a risk without necessarily fixing it, often because the cost of fixing it outweighs the benefit"}}, {"id": "b", "text": {"en": "Ignoring all risks entirely without any decision"}}, {"id": "c", "text": {"en": "Automatically fixing every risk regardless of cost"}}, {"id": "d", "text": {"en": "Transferring the risk to an insurance company"}}]', 'a', null, 3),
  ('quick_check', '5e64124f-7242-4575-7262-2e4252536f7b', null, null, '{"en": "The overall goal of risk assessment is to:"}', '[{"id": "a", "text": {"en": "Eliminate all risk completely, which is achievable with enough budget"}}, {"id": "b", "text": {"en": "Randomly select which vulnerabilities to fix"}}, {"id": "c", "text": {"en": "Make informed, deliberate decisions about which risks are worth addressing"}}, {"id": "d", "text": {"en": "Ignore likelihood and focus only on impact"}}]', 'c', null, 4),
  ('quick_check', '6f75235a-8353-4686-8373-3f5363647a8c', null, null, '{"en": "ISO 27001 is:"}', '[{"id": "a", "text": {"en": "A U.S. government law"}}, {"id": "b", "text": {"en": "A type of firewall"}}, {"id": "c", "text": {"en": "An international standard for building and maintaining an Information Security Management System"}}, {"id": "d", "text": {"en": "A single antivirus product"}}]', 'c', null, 1),
  ('quick_check', '6f75235a-8353-4686-8373-3f5363647a8c', null, null, '{"en": "The NIST Cybersecurity Framework organizes practice around five functions, including:"}', '[{"id": "a", "text": {"en": "Identify, Protect, Detect, Respond, and Recover"}}, {"id": "b", "text": {"en": "Only \"Protect\" and nothing else"}}, {"id": "c", "text": {"en": "Marketing, Sales, and Support"}}, {"id": "d", "text": {"en": "Encryption, Firewalls, and VPNs exclusively"}}]', 'a', null, 2),
  ('quick_check', '6f75235a-8353-4686-8373-3f5363647a8c', null, null, '{"en": "GDPR is:"}', '[{"id": "a", "text": {"en": "An optional guideline with no legal weight"}}, {"id": "b", "text": {"en": "A certification for individual security professionals"}}, {"id": "c", "text": {"en": "A framework specific to the United States only"}}, {"id": "d", "text": {"en": "A European Union regulation with legal force and financial penalties for violations"}}]', 'd', null, 3),
  ('quick_check', '6f75235a-8353-4686-8373-3f5363647a8c', null, null, '{"en": "Understanding major frameworks and regulations helps explain:"}', '[{"id": "a", "text": {"en": "Nothing relevant to everyday security work"}}, {"id": "b", "text": {"en": "Why certain security decisions get made the way they do in real organizations"}}, {"id": "c", "text": {"en": "Only how to pass an exam"}}, {"id": "d", "text": {"en": "How to write malware"}}]', 'b', null, 4),
  ('quick_check', '70862469-9464-4797-9484-4a6474758b9d', null, null, '{"en": "The core principle of Zero Trust is:"}', '[{"id": "a", "text": {"en": "Trusting all internal network traffic by default"}}, {"id": "b", "text": {"en": "Building one extremely strong perimeter firewall"}}, {"id": "c", "text": {"en": "Never trusting any user, device, or system by default, regardless of location"}}, {"id": "d", "text": {"en": "Eliminating the need for authentication"}}]', 'c', null, 1),
  ('quick_check', '70862469-9464-4797-9484-4a6474758b9d', null, null, '{"en": "The traditional \"castle and moat\" security model assumed:"}', '[{"id": "a", "text": {"en": "Once inside the network perimeter, users and devices are generally trusted"}}, {"id": "b", "text": {"en": "No trust should ever be granted anywhere"}}, {"id": "c", "text": {"en": "The internet doesn''t exist"}}, {"id": "d", "text": {"en": "Every device must be verified constantly"}}]', 'a', null, 2),
  ('quick_check', '70862469-9464-4797-9484-4a6474758b9d', null, null, '{"en": "Why did the shift toward Zero Trust happen?"}', '[{"id": "a", "text": {"en": "Firewalls became illegal"}}, {"id": "b", "text": {"en": "Passwords were banned"}}, {"id": "c", "text": {"en": "It has no real cause"}}, {"id": "d", "text": {"en": "Remote work, cloud services, and mobile devices erased the traditional network perimeter"}}]', 'd', null, 3),
  ('quick_check', '70862469-9464-4797-9484-4a6474758b9d', null, null, '{"en": "\"Assume breach\" as a Zero Trust tenet means:"}', '[{"id": "a", "text": {"en": "Assuming no breach will ever happen"}}, {"id": "b", "text": {"en": "Designing systems as if an attacker is already inside, minimizing what any single point can reach"}}, {"id": "c", "text": {"en": "Ignoring security entirely"}}, {"id": "d", "text": {"en": "Only protecting the network''s outer edge"}}]', 'b', null, 4),
  ('quick_check', '81973570-a575-48a8-a595-5b75859c6a0e', null, null, '{"en": "Microsegmentation, compared to traditional network segmentation, is:"}', '[{"id": "a", "text": {"en": "Exactly the same thing with a different name"}}, {"id": "b", "text": {"en": "Broader and less specific"}}, {"id": "c", "text": {"en": "Focused only on physical hardware"}}, {"id": "d", "text": {"en": "Far more fine-grained, sometimes down to individual applications or workloads"}}]', 'd', null, 1),
  ('quick_check', '81973570-a575-48a8-a595-5b75859c6a0e', null, null, '{"en": "Lateral movement refers to:"}', '[{"id": "a", "text": {"en": "Data traveling to a backup server"}}, {"id": "b", "text": {"en": "An attacker moving from one compromised system to others within a network"}}, {"id": "c", "text": {"en": "A type of encryption"}}, {"id": "d", "text": {"en": "Physical movement of hardware"}}]', 'b', null, 2),
  ('quick_check', '81973570-a575-48a8-a595-5b75859c6a0e', null, null, '{"en": "Microsegmentation is specifically designed to:"}', '[{"id": "a", "text": {"en": "Make lateral movement as difficult as possible for an attacker"}}, {"id": "b", "text": {"en": "Eliminate the need for any authentication"}}, {"id": "c", "text": {"en": "Increase network speed"}}, {"id": "d", "text": {"en": "Replace the need for firewalls entirely"}}]', 'a', null, 3),
  ('quick_check', '81973570-a575-48a8-a595-5b75859c6a0e', null, null, '{"en": "What makes microsegmentation practical at scale today?"}', '[{"id": "a", "text": {"en": "Nothing has changed; it''s always been easy"}}, {"id": "b", "text": {"en": "Physical rewiring for every new rule"}}, {"id": "c", "text": {"en": "Software-defined networking and modern tools enforcing rules dynamically"}}, {"id": "d", "text": {"en": "It''s actually impossible to implement"}}]', 'c', null, 4),
  ('quick_check', '92a84681-b686-49b9-b6a6-6c8696ad7b1f', null, null, '{"en": "Continuous verification means:"}', '[{"id": "a", "text": {"en": "Checking identity only once at login"}}, {"id": "b", "text": {"en": "Access decisions get reevaluated repeatedly throughout a session"}}, {"id": "c", "text": {"en": "Never checking any signals after initial login"}}, {"id": "d", "text": {"en": "Only checking passwords, nothing else"}}]', 'b', null, 1),
  ('quick_check', '92a84681-b686-49b9-b6a6-6c8696ad7b1f', null, null, '{"en": "\"Device health\" as a verification signal refers to:"}', '[{"id": "a", "text": {"en": "The physical temperature of a device"}}, {"id": "b", "text": {"en": "The device''s battery level only"}}, {"id": "c", "text": {"en": "Whether the device still meets security requirements, like being updated and not compromised"}}, {"id": "d", "text": {"en": "The device''s brand name"}}]', 'c', null, 2),
  ('quick_check', '92a84681-b686-49b9-b6a6-6c8696ad7b1f', null, null, '{"en": "Why does continuous verification matter more than a one-time login check?"}', '[{"id": "a", "text": {"en": "It doesn''t actually matter more"}}, {"id": "b", "text": {"en": "Credentials are never stolen in practice"}}, {"id": "c", "text": {"en": "One-time checks are always sufficient"}}, {"id": "d", "text": {"en": "A one-time check can''t catch what happens after that initial moment, like a stolen session or mid-session compromise"}}]', 'd', null, 3),
  ('quick_check', '92a84681-b686-49b9-b6a6-6c8696ad7b1f', null, null, '{"en": "The bigger shift continuous verification represents is:"}', '[{"id": "a", "text": {"en": "Moving from a single identity check to continuously asking whether the ongoing session still makes sense"}}, {"id": "b", "text": {"en": "Removing all verification entirely"}}, {"id": "c", "text": {"en": "Only verifying users once a year"}}, {"id": "d", "text": {"en": "Trusting every session permanently after the first check"}}]', 'a', null, 4),
  ('quick_check', 'a395579a-c797-4aca-c7b7-7d97a7be8c2a', null, null, '{"en": "Containers, unlike traditional virtual machines, typically:"}', '[{"id": "a", "text": {"en": "Each run a completely separate operating system"}}, {"id": "b", "text": {"en": "Share the underlying operating system kernel with other containers"}}, {"id": "c", "text": {"en": "Are always slower to start than VMs"}}, {"id": "d", "text": {"en": "Have no security considerations at all"}}]', 'b', null, 1),
  ('quick_check', 'a395579a-c797-4aca-c7b7-7d97a7be8c2a', null, null, '{"en": "A container escape is:"}', '[{"id": "a", "text": {"en": "A normal, harmless container shutdown"}}, {"id": "b", "text": {"en": "A type of encryption"}}, {"id": "c", "text": {"en": "A backup procedure"}}, {"id": "d", "text": {"en": "A flaw that lets code break out of its container boundary, potentially reaching the host"}}]', 'd', null, 2),
  ('quick_check', 'a395579a-c797-4aca-c7b7-7d97a7be8c2a', null, null, '{"en": "A vulnerable base image problem occurs when:"}', '[{"id": "a", "text": {"en": "A container is built on top of an outdated or already-compromised base image, inheriting its flaws"}}, {"id": "b", "text": {"en": "A container has too little functionality"}}, {"id": "c", "text": {"en": "A container runs too fast"}}, {"id": "d", "text": {"en": "A container uses too much memory"}}]', 'a', null, 3),
  ('quick_check', 'a395579a-c797-4aca-c7b7-7d97a7be8c2a', null, null, '{"en": "Good container security practice includes:"}', '[{"id": "a", "text": {"en": "Storing secrets directly inside container images for convenience"}}, {"id": "b", "text": {"en": "Running every container as root by default"}}, {"id": "c", "text": {"en": "Scanning images for known vulnerabilities before deployment"}}, {"id": "d", "text": {"en": "Never updating base images"}}]', 'c', null, 4),
  ('quick_check', 'b4a668ab-d8a8-4bdb-d8c8-8ea8b8cf9d3b', null, null, '{"en": "A CI/CD pipeline is:"}', '[{"id": "a", "text": {"en": "A type of firewall"}}, {"id": "b", "text": {"en": "A physical network cable"}}, {"id": "c", "text": {"en": "An automated process that builds, tests, and deploys code, often with minimal human involvement"}}, {"id": "d", "text": {"en": "A password policy"}}]', 'c', null, 1),
  ('quick_check', 'b4a668ab-d8a8-4bdb-d8c8-8ea8b8cf9d3b', null, null, '{"en": "Why has the CI/CD pipeline become a serious attack target?"}', '[{"id": "a", "text": {"en": "Compromising it can let an attacker inject malicious code that ships to production automatically"}}, {"id": "b", "text": {"en": "It has no real value to attackers"}}, {"id": "c", "text": {"en": "It''s always completely isolated from the internet"}}, {"id": "d", "text": {"en": "It only affects test environments, never production"}}]', 'a', null, 2),
  ('quick_check', 'b4a668ab-d8a8-4bdb-d8c8-8ea8b8cf9d3b', null, null, '{"en": "Dependency poisoning refers to:"}', '[{"id": "a", "text": {"en": "A hardware failure"}}, {"id": "b", "text": {"en": "A type of firewall rule"}}, {"id": "c", "text": {"en": "A password reset procedure"}}, {"id": "d", "text": {"en": "Injecting malicious code into a third-party package that gets automatically pulled into a build"}}]', 'd', null, 3),
  ('quick_check', 'b4a668ab-d8a8-4bdb-d8c8-8ea8b8cf9d3b', null, null, '{"en": "Secure CI/CD practice includes:"}', '[{"id": "a", "text": {"en": "Giving every developer unrestricted pipeline access"}}, {"id": "b", "text": {"en": "Requiring code review and approval gates before changes reach the pipeline"}}, {"id": "c", "text": {"en": "Never scanning dependencies for vulnerabilities"}}, {"id": "d", "text": {"en": "Storing pipeline credentials with no rotation or monitoring"}}]', 'b', null, 4),
  ('quick_check', 'c5b779bc-e9b9-4cec-e9d9-9fb9c9d0e4c9', null, null, '{"en": "Kubernetes primarily helps with:"}', '[{"id": "a", "text": {"en": "Automatically deploying, scaling, and managing containers across a cluster of machines"}}, {"id": "b", "text": {"en": "Writing application code"}}, {"id": "c", "text": {"en": "Designing user interfaces"}}, {"id": "d", "text": {"en": "Physical server manufacturing"}}]', 'a', null, 1),
  ('quick_check', 'c5b779bc-e9b9-4cec-e9d9-9fb9c9d0e4c9', null, null, '{"en": "Compromising the Kubernetes control plane can potentially give an attacker:"}', '[{"id": "a", "text": {"en": "Access to nothing significant"}}, {"id": "b", "text": {"en": "Only cosmetic changes to a dashboard"}}, {"id": "c", "text": {"en": "Access to a single, isolated container only"}}, {"id": "d", "text": {"en": "Control over the entire cluster and everything running on it"}}]', 'd', null, 2),
  ('quick_check', 'c5b779bc-e9b9-4cec-e9d9-9fb9c9d0e4c9', null, null, '{"en": "One of the most common, dangerous real-world Kubernetes misconfigurations is:"}', '[{"id": "a", "text": {"en": "Using too much RBAC"}}, {"id": "b", "text": {"en": "The API server exposed to the internet without proper authentication"}}, {"id": "c", "text": {"en": "Having too many namespaces"}}, {"id": "d", "text": {"en": "Updating the cluster too frequently"}}]', 'b', null, 3),
  ('quick_check', 'c5b779bc-e9b9-4cec-e9d9-9fb9c9d0e4c9', null, null, '{"en": "Kubernetes network policies are used to:"}', '[{"id": "a", "text": {"en": "Increase overall cluster speed only"}}, {"id": "b", "text": {"en": "Automatically write application code"}}, {"id": "c", "text": {"en": "Control which pods can actually communicate with each other, similar to microsegmentation"}}, {"id": "d", "text": {"en": "Replace the need for RBAC entirely"}}]', 'c', null, 4),
  ('quick_check', 'd6c88acd-facb-4dfc-fae0-a0cadad1f5da', null, null, '{"en": "Traditional signature-based antivirus has an obvious blind spot:"}', '[{"id": "a", "text": {"en": "It works perfectly against everything"}}, {"id": "b", "text": {"en": "It requires no updates ever"}}, {"id": "c", "text": {"en": "It''s too fast to be useful"}}, {"id": "d", "text": {"en": "It can only catch threats it already recognizes from its signature database"}}]', 'd', null, 1),
  ('quick_check', 'd6c88acd-facb-4dfc-fae0-a0cadad1f5da', null, null, '{"en": "Behavioral analysis in endpoint protection works by:"}', '[{"id": "a", "text": {"en": "Only checking file names"}}, {"id": "b", "text": {"en": "Watching for suspicious patterns of behavior, like rapid mass file encryption"}}, {"id": "c", "text": {"en": "Ignoring all running programs"}}, {"id": "d", "text": {"en": "Deleting every file automatically"}}]', 'b', null, 2),
  ('quick_check', 'd6c88acd-facb-4dfc-fae0-a0cadad1f5da', null, null, '{"en": "Polymorphism, in the context of malware, refers to:"}', '[{"id": "a", "text": {"en": "Malicious code changing its own signature while keeping its harmful behavior intact"}}, {"id": "b", "text": {"en": "A type of firewall"}}, {"id": "c", "text": {"en": "A backup strategy"}}, {"id": "d", "text": {"en": "A password policy"}}]', 'a', null, 3),
  ('quick_check', 'd6c88acd-facb-4dfc-fae0-a0cadad1f5da', null, null, '{"en": "Why has endpoint protection kept evolving beyond simple antivirus?"}', '[{"id": "a", "text": {"en": "It hasn''t actually changed at all"}}, {"id": "b", "text": {"en": "Antivirus was always sufficient"}}, {"id": "c", "text": {"en": "Attackers actively modify malware to dodge signature detection, requiring behavior-based approaches"}}, {"id": "d", "text": {"en": "Endpoints are no longer targeted by attackers"}}]', 'c', null, 4),
  ('quick_check', 'e7d99bde-0bdc-4e0d-0bf1-b1dbebe206eb', null, null, '{"en": "EDR stands for:"}', '[{"id": "a", "text": {"en": "Extended Data Retrieval"}}, {"id": "b", "text": {"en": "Encrypted Data Router"}}, {"id": "c", "text": {"en": "Endpoint Detection and Response"}}, {"id": "d", "text": {"en": "External Device Restriction"}}]', 'c', null, 1),
  ('quick_check', 'e7d99bde-0bdc-4e0d-0bf1-b1dbebe206eb', null, null, '{"en": "EDR tools continuously record:"}', '[{"id": "a", "text": {"en": "Detailed activity like process launches, file changes, and network connections on each endpoint"}}, {"id": "b", "text": {"en": "Only the device''s battery status"}}, {"id": "c", "text": {"en": "Nothing useful for investigation"}}, {"id": "d", "text": {"en": "Only user login times, and nothing else"}}]', 'a', null, 2),
  ('quick_check', 'e7d99bde-0bdc-4e0d-0bf1-b1dbebe206eb', null, null, '{"en": "What does EDR add beyond basic endpoint protection?"}', '[{"id": "a", "text": {"en": "Nothing meaningfully different"}}, {"id": "b", "text": {"en": "Only a nicer-looking dashboard"}}, {"id": "c", "text": {"en": "Slower detection times"}}, {"id": "d", "text": {"en": "Active response capability, like isolating a compromised endpoint automatically"}}]', 'd', null, 3),
  ('quick_check', 'e7d99bde-0bdc-4e0d-0bf1-b1dbebe206eb', null, null, '{"en": "Why does \"detection AND response\" matter as a combined concept?"}', '[{"id": "a", "text": {"en": "Detection alone is always sufficient"}}, {"id": "b", "text": {"en": "Detecting a threat without the ability to act on it quickly still leaves the door open"}}, {"id": "c", "text": {"en": "Response without detection is more effective"}}, {"id": "d", "text": {"en": "Neither detection nor response actually matters"}}]', 'b', null, 4),
  ('quick_check', 'f8ea0cef-1cee-4f1e-1c02-c2ecfcf317fc', null, null, '{"en": "Endpoint hardening is primarily about:"}', '[{"id": "a", "text": {"en": "Reducing the number of ways an endpoint can actually be attacked"}}, {"id": "b", "text": {"en": "Making an endpoint run faster"}}, {"id": "c", "text": {"en": "Adding more installed software"}}, {"id": "d", "text": {"en": "Increasing the attack surface deliberately"}}]', 'a', null, 1),
  ('quick_check', 'f8ea0cef-1cee-4f1e-1c02-c2ecfcf317fc', null, null, '{"en": "Why should unnecessary software be removed from an endpoint?"}', '[{"id": "a", "text": {"en": "It has no relationship to security"}}, {"id": "b", "text": {"en": "It always improves performance"}}, {"id": "c", "text": {"en": "It''s required by law"}}, {"id": "d", "text": {"en": "Every installed application is a potential vulnerability waiting to be discovered"}}]', 'd', null, 2),
  ('quick_check', 'f8ea0cef-1cee-4f1e-1c02-c2ecfcf317fc', null, null, '{"en": "Application allowlisting works by:"}', '[{"id": "a", "text": {"en": "Blocking only known-bad software"}}, {"id": "b", "text": {"en": "Only permitting pre-approved applications to run, blocking everything else by default"}}, {"id": "c", "text": {"en": "Allowing absolutely any application to run"}}, {"id": "d", "text": {"en": "Deleting all applications automatically"}}]', 'b', null, 3),
  ('quick_check', 'f8ea0cef-1cee-4f1e-1c02-c2ecfcf317fc', null, null, '{"en": "Why does hardening matter alongside detection tools like EDR?"}', '[{"id": "a", "text": {"en": "Hardening replaces the need for EDR entirely"}}, {"id": "b", "text": {"en": "They''re unrelated and don''t work together"}}, {"id": "c", "text": {"en": "Every risk reduced through hardening is one less thing EDR ever needs to catch"}}, {"id": "d", "text": {"en": "EDR makes hardening completely unnecessary"}}]', 'c', null, 4),
  ('quick_check', '09fb1df0-2dff-4020-2d13-d3fdfdf428fd', null, null, '{"en": "Business Continuity (BC) primarily focuses on:"}', '[{"id": "a", "text": {"en": "Restoring IT systems after a disruption"}}, {"id": "b", "text": {"en": "Preventing every possible disruption completely"}}, {"id": "c", "text": {"en": "Keeping critical business functions running during a disruption"}}, {"id": "d", "text": {"en": "Only IT-specific recovery tasks"}}]', 'c', null, 1),
  ('quick_check', '09fb1df0-2dff-4020-2d13-d3fdfdf428fd', null, null, '{"en": "Disaster Recovery (DR) primarily focuses on:"}', '[{"id": "a", "text": {"en": "Restoring IT systems and data after a disruption"}}, {"id": "b", "text": {"en": "Keeping staff physically comfortable"}}, {"id": "c", "text": {"en": "Marketing during a crisis"}}, {"id": "d", "text": {"en": "Ignoring the disruption entirely"}}]', 'a', null, 2),
  ('quick_check', '09fb1df0-2dff-4020-2d13-d3fdfdf428fd', null, null, '{"en": "A simple way to distinguish BC from DR is:"}', '[{"id": "a", "text": {"en": "They''re actually identical concepts"}}, {"id": "b", "text": {"en": "BC only applies to natural disasters"}}, {"id": "c", "text": {"en": "DR only applies to cyberattacks"}}, {"id": "d", "text": {"en": "BC asks how to keep functioning now, DR asks how to get systems fully back to normal"}}]', 'd', null, 3),
  ('quick_check', '09fb1df0-2dff-4020-2d13-d3fdfdf428fd', null, null, '{"en": "An organization with a strong DR plan but no BC plan might:"}', '[{"id": "a", "text": {"en": "Never experience any problems"}}, {"id": "b", "text": {"en": "Still grind to a halt for hours because no one planned how staff would keep working during the outage"}}, {"id": "c", "text": {"en": "Automatically have a strong BC plan too"}}, {"id": "d", "text": {"en": "Have no need for backups"}}]', 'b', null, 4),
  ('quick_check', '1a0c2ea1-3e00-4131-3e24-e4a0a1a539ae', null, null, '{"en": "Recovery Time Objective (RTO) measures:"}', '[{"id": "a", "text": {"en": "How much data can be lost"}}, {"id": "b", "text": {"en": "The cost of a backup solution"}}, {"id": "c", "text": {"en": "The number of employees affected"}}, {"id": "d", "text": {"en": "How long a system can realistically be down before impact becomes unacceptable"}}]', 'd', null, 1),
  ('quick_check', '1a0c2ea1-3e00-4131-3e24-e4a0a1a539ae', null, null, '{"en": "Recovery Point Objective (RPO) measures:"}', '[{"id": "a", "text": {"en": "How fast a system can be restarted"}}, {"id": "b", "text": {"en": "How much data, measured in time, the organization can afford to lose"}}, {"id": "c", "text": {"en": "The physical location of backups"}}, {"id": "d", "text": {"en": "The number of servers involved"}}]', 'b', null, 2),
  ('quick_check', '1a0c2ea1-3e00-4131-3e24-e4a0a1a539ae', null, null, '{"en": "Why do RTO and RPO matter practically?"}', '[{"id": "a", "text": {"en": "They directly determine the technical solution required and its cost"}}, {"id": "b", "text": {"en": "They have no real practical impact"}}, {"id": "c", "text": {"en": "They only matter for very small companies"}}, {"id": "d", "text": {"en": "They''re purely theoretical numbers with no application"}}]', 'a', null, 3),
  ('quick_check', '1a0c2ea1-3e00-4131-3e24-e4a0a1a539ae', null, null, '{"en": "A common mistake organizations make with RTO/RPO is:"}', '[{"id": "a", "text": {"en": "Setting them too precisely"}}, {"id": "b", "text": {"en": "Never using them at all"}}, {"id": "c", "text": {"en": "Treating every system as equally critical, wasting resources or under-protecting what matters most"}}, {"id": "d", "text": {"en": "Only applying them to marketing systems"}}]', 'c', null, 4),
  ('quick_check', '2b1d3fb2-4f11-4242-4f35-f5b1b2b64abf', null, null, '{"en": "A tabletop exercise involves:"}', '[{"id": "a", "text": {"en": "The team talking through a scenario step by step without touching actual systems"}}, {"id": "b", "text": {"en": "Fully failing over to backup systems in production"}}, {"id": "c", "text": {"en": "Ignoring the plan entirely"}}, {"id": "d", "text": {"en": "Only reading the plan silently alone"}}]', 'a', null, 1),
  ('quick_check', '2b1d3fb2-4f11-4242-4f35-f5b1b2b64abf', null, null, '{"en": "Which of these is the most realistic form of BC/DR testing?"}', '[{"id": "a", "text": {"en": "Never testing at all"}}, {"id": "b", "text": {"en": "Only reading the plan once"}}, {"id": "c", "text": {"en": "A full simulation, actually failing over and restoring from real backups"}}, {"id": "d", "text": {"en": "Guessing what might happen"}}]', 'c', null, 2),
  ('quick_check', '2b1d3fb2-4f11-4242-4f35-f5b1b2b64abf', null, null, '{"en": "Testing a BC/DR plan commonly reveals:"}', '[{"id": "a", "text": {"en": "That plans never have any flaws"}}, {"id": "b", "text": {"en": "Nothing useful ever"}}, {"id": "c", "text": {"en": "That testing is unnecessary"}}, {"id": "d", "text": {"en": "Backups that wouldn''t actually restore properly, or outdated contact information"}}]', 'd', null, 3),
  ('quick_check', '2b1d3fb2-4f11-4242-4f35-f5b1b2b64abf', null, null, '{"en": "Why does regular BC/DR testing matter so much?"}', '[{"id": "a", "text": {"en": "It has no real value"}}, {"id": "b", "text": {"en": "The worst moment to discover a plan doesn''t work is during an actual crisis"}}, {"id": "c", "text": {"en": "Plans never need updating once written"}}, {"id": "d", "text": {"en": "Testing replaces the need for a written plan entirely"}}]', 'b', null, 4),
  ('quick_check', '3c2e40c3-5022-4353-5046-062c2c375bc0', null, null, '{"en": "Third-party risk refers to:"}', '[{"id": "a", "text": {"en": "Risk that only exists within your own organization"}}, {"id": "b", "text": {"en": "A type of firewall"}}, {"id": "c", "text": {"en": "The security exposure introduced by every vendor, contractor, and service provider connected to your systems"}}, {"id": "d", "text": {"en": "A risk that never actually matters in practice"}}]', 'c', null, 1),
  ('quick_check', '3c2e40c3-5022-4353-5046-062c2c375bc0', null, null, '{"en": "Why do attackers often target third parties rather than a well-defended organization directly?"}', '[{"id": "a", "text": {"en": "The weakest link in the chain is often easier to compromise"}}, {"id": "b", "text": {"en": "Third parties are never actually connected to anything important"}}, {"id": "c", "text": {"en": "It''s illegal to attack the main organization"}}, {"id": "d", "text": {"en": "Third parties are always better defended"}}]', 'a', null, 2),
  ('quick_check', '3c2e40c3-5022-4353-5046-062c2c375bc0', null, null, '{"en": "Software dependencies as a third-party risk category means:"}', '[{"id": "a", "text": {"en": "Your software has no external dependencies ever"}}, {"id": "b", "text": {"en": "Dependencies have nothing to do with security"}}, {"id": "c", "text": {"en": "Every third-party library or service your software relies on inherits that provider''s security posture"}}, {"id": "d", "text": {"en": "Only hardware counts as a dependency"}}]', 'd', null, 3),
  ('quick_check', '3c2e40c3-5022-4353-5046-062c2c375bc0', null, null, '{"en": "The uncomfortable truth about supply chain security is that:"}', '[{"id": "a", "text": {"en": "You always have full control over every vendor"}}, {"id": "b", "text": {"en": "You can''t fully control a vendor''s security the way you control your own"}}, {"id": "c", "text": {"en": "Vendors never pose any real risk"}}, {"id": "d", "text": {"en": "It requires no ongoing process at all"}}]', 'b', null, 4),
  ('quick_check', '4d3f51d4-6133-4464-6157-173d3d486cd1', null, null, '{"en": "A software supply chain attack typically involves:"}', '[{"id": "a", "text": {"en": "Attacking thousands of individual targets one at a time directly"}}, {"id": "b", "text": {"en": "No trust relationship at all"}}, {"id": "c", "text": {"en": "Only physical theft of hardware"}}, {"id": "d", "text": {"en": "Compromising a single trusted piece of software that many organizations then willingly install"}}]', 'd', null, 1),
  ('quick_check', '4d3f51d4-6133-4464-6157-173d3d486cd1', null, null, '{"en": "Typosquatting applied to software packages means:"}', '[{"id": "a", "text": {"en": "Making genuine typing mistakes while coding"}}, {"id": "b", "text": {"en": "Publishing a malicious package with a name deceptively similar to a popular one"}}, {"id": "c", "text": {"en": "A type of firewall setting"}}, {"id": "d", "text": {"en": "A backup naming convention"}}]', 'b', null, 2),
  ('quick_check', '4d3f51d4-6133-4464-6157-173d3d486cd1', null, null, '{"en": "Why are software supply chain attacks so devastating?"}', '[{"id": "a", "text": {"en": "They exploit trust at scale, reaching many organizations through one compromised source"}}, {"id": "b", "text": {"en": "They only ever affect one organization at a time"}}, {"id": "c", "text": {"en": "They''re always immediately obvious to victims"}}, {"id": "d", "text": {"en": "They have no real impact in practice"}}]', 'a', null, 3),
  ('quick_check', '4d3f51d4-6133-4464-6157-173d3d486cd1', null, null, '{"en": "A recommended defense approach against supply chain attacks includes:"}', '[{"id": "a", "text": {"en": "Trusting every vendor completely with no further verification"}}, {"id": "b", "text": {"en": "Ignoring what software is actually running in your environment"}}, {"id": "c", "text": {"en": "Monitoring software behavior even after installation and maintaining a clear software inventory"}}, {"id": "d", "text": {"en": "Never updating any software ever"}}]', 'c', null, 4),
  ('quick_check', '5e405fe6-7244-4575-7269-2846b4e69ea3', null, null, '{"en": "A Software Bill of Materials (SBOM) is:"}', '[{"id": "a", "text": {"en": "A detailed inventory of every component, library, and dependency that makes up an application"}}, {"id": "b", "text": {"en": "A financial invoice for software purchases"}}, {"id": "c", "text": {"en": "A type of firewall"}}, {"id": "d", "text": {"en": "A backup schedule"}}]', 'a', null, 1),
  ('quick_check', '5e405fe6-7244-4575-7269-2846b4e69ea3', null, null, '{"en": "Why is an SBOM valuable when a new vulnerability is discovered in some dependency?"}', '[{"id": "a", "text": {"en": "It has no practical value"}}, {"id": "b", "text": {"en": "It automatically fixes every vulnerability"}}, {"id": "c", "text": {"en": "It replaces the need for patching entirely"}}, {"id": "d", "text": {"en": "It lets you quickly determine whether that vulnerable dependency is actually present in your software"}}]', 'd', null, 2),
  ('quick_check', '5e405fe6-7244-4575-7269-2846b4e69ea3', null, null, '{"en": "Least privilege applied to vendors means:"}', '[{"id": "a", "text": {"en": "Giving every vendor full access to everything"}}, {"id": "b", "text": {"en": "Giving a vendor only the access genuinely required for their specific role"}}, {"id": "c", "text": {"en": "Removing all vendor access permanently"}}, {"id": "d", "text": {"en": "Ignoring what access vendors actually have"}}]', 'b', null, 3),
  ('quick_check', '5e405fe6-7244-4575-7269-2846b4e69ea3', null, null, '{"en": "Why should supply chain security be treated as an ongoing discipline rather than a one-time audit?"}', '[{"id": "a", "text": {"en": "A vendor''s security posture is always permanently fixed once assessed"}}, {"id": "b", "text": {"en": "One-time audits are always sufficient"}}, {"id": "c", "text": {"en": "A vendor''s security posture can change over time, so continuous monitoring matters"}}, {"id": "d", "text": {"en": "Ongoing monitoring has no real value"}}]', 'c', null, 4),
  ('quick_check', '6f516ae7-8355-4686-8370-395c5c7a0fb4', null, null, '{"en": "Prompt injection is best understood as:"}', '[{"id": "a", "text": {"en": "A type of network firewall"}}, {"id": "b", "text": {"en": "A backup strategy for AI systems"}}, {"id": "c", "text": {"en": "The AI-era equivalent of injection attacks, where hidden instructions get embedded in content an AI processes"}}, {"id": "d", "text": {"en": "A password policy specific to AI tools"}}]', 'c', null, 1),
  ('quick_check', '6f516ae7-8355-4686-8370-395c5c7a0fb4', null, null, '{"en": "In a realistic prompt injection scenario, hidden instructions might be embedded in:"}', '[{"id": "a", "text": {"en": "A webpage or document the AI is asked to summarize"}}, {"id": "b", "text": {"en": "Only in the AI''s original training data"}}, {"id": "c", "text": {"en": "Nowhere; this scenario never actually happens"}}, {"id": "d", "text": {"en": "Only in encrypted files that can''t be read"}}]', 'a', null, 2),
  ('quick_check', '6f516ae7-8355-4686-8370-395c5c7a0fb4', null, null, '{"en": "Why is prompt injection a genuinely hard problem to solve?"}', '[{"id": "a", "text": {"en": "It isn''t actually a hard problem at all"}}, {"id": "b", "text": {"en": "AI systems never process any external text"}}, {"id": "c", "text": {"en": "It''s identical to a hardware failure"}}, {"id": "d", "text": {"en": "Language models process everything as text, and the boundary between instructions and untrusted content isn''t always structurally enforced"}}]', 'd', null, 3),
  ('quick_check', '6f516ae7-8355-4686-8370-395c5c7a0fb4', null, null, '{"en": "Jailbreaking, in the context of AI, refers to:"}', '[{"id": "a", "text": {"en": "A physical security bypass technique"}}, {"id": "b", "text": {"en": "Crafting inputs specifically designed to bypass an AI system''s safety guidelines"}}, {"id": "c", "text": {"en": "A type of encryption"}}, {"id": "d", "text": {"en": "A network segmentation technique"}}]', 'b', null, 4),
  ('quick_check', '70627bf8-9466-4797-9481-4a6d6d8b10c5', null, null, '{"en": "Data poisoning is:"}', '[{"id": "a", "text": {"en": "A physical attack on server hardware"}}, {"id": "b", "text": {"en": "A type of firewall rule"}}, {"id": "c", "text": {"en": "A backup corruption issue only"}}, {"id": "d", "text": {"en": "An attack where corrupted or misleading data is deliberately introduced to influence what a model learns"}}]', 'd', null, 1),
  ('quick_check', '70627bf8-9466-4797-9481-4a6d6d8b10c5', null, null, '{"en": "A backdoor attack on a machine learning model:"}', '[{"id": "a", "text": {"en": "Always makes the model obviously malfunction immediately"}}, {"id": "b", "text": {"en": "Makes the model behave normally except when it encounters a specific attacker-planted trigger"}}, {"id": "c", "text": {"en": "Has nothing to do with training data"}}, {"id": "d", "text": {"en": "Is identical to a network firewall bypass"}}]', 'b', null, 2),
  ('quick_check', '70627bf8-9466-4797-9481-4a6d6d8b10c5', null, null, '{"en": "Why are backdoor attacks especially hard to catch through normal testing?"}', '[{"id": "a", "text": {"en": "The model looks fine unless you happen to test for that exact trigger"}}, {"id": "b", "text": {"en": "They''re always caught immediately by any test"}}, {"id": "c", "text": {"en": "They don''t actually affect model behavior at all"}}, {"id": "d", "text": {"en": "Testing has no relevance to this issue"}}]', 'a', null, 3),
  ('quick_check', '70627bf8-9466-4797-9481-4a6d6d8b10c5', null, null, '{"en": "Model provenance refers to:"}', '[{"id": "a", "text": {"en": "The model''s file size"}}, {"id": "b", "text": {"en": "The color scheme of a model''s interface"}}, {"id": "c", "text": {"en": "Where a model came from and how it was trained"}}, {"id": "d", "text": {"en": "The model''s programming language"}}]', 'c', null, 4),
  ('quick_check', '81738c09-a577-48a8-a592-5b7e7e9c21d6', null, null, '{"en": "Anomaly detection using AI in cybersecurity works by:"}', '[{"id": "a", "text": {"en": "Learning what \"normal\" activity looks like and flagging genuine deviations from it"}}, {"id": "b", "text": {"en": "Randomly flagging activity with no learning involved"}}, {"id": "c", "text": {"en": "Only detecting physical hardware failures"}}, {"id": "d", "text": {"en": "Replacing the need for any human analyst entirely"}}]', 'a', null, 1),
  ('quick_check', '81738c09-a577-48a8-a592-5b7e7e9c21d6', null, null, '{"en": "A genuine limitation of AI-based security tools is that:"}', '[{"id": "a", "text": {"en": "They are always completely accurate with zero errors"}}, {"id": "b", "text": {"en": "They have no limitations whatsoever"}}, {"id": "c", "text": {"en": "They never require any human oversight"}}, {"id": "d", "text": {"en": "They make probabilistic judgments and can produce false positives and false negatives"}}]', 'd', null, 2),
  ('quick_check', '81738c09-a577-48a8-a592-5b7e7e9c21d6', null, null, '{"en": "Adversarial awareness, in this context, refers to:"}', '[{"id": "a", "text": {"en": "AI systems being aware of nothing at all"}}, {"id": "b", "text": {"en": "Sophisticated attackers studying how AI-based defenses work in order to evade them"}}, {"id": "c", "text": {"en": "A type of encryption"}}, {"id": "d", "text": {"en": "A backup strategy"}}]', 'b', null, 3),
  ('quick_check', '81738c09-a577-48a8-a592-5b7e7e9c21d6', null, null, '{"en": "The course''s closing thought emphasizes that:"}', '[{"id": "a", "text": {"en": "AI replaces every fundamental concept learned earlier in this course"}}, {"id": "b", "text": {"en": "Technology change makes earlier fundamentals irrelevant"}}, {"id": "c", "text": {"en": "Understanding how something works, how it can be abused, and how to respond in layers is the pattern that stays useful regardless of the technology"}}, {"id": "d", "text": {"en": "Only the newest technology matters going forward"}}]', 'c', null, 4),
  ('quick_check', '928490fa-b688-49b9-b6a3-6c918f0332e7', null, null, '{"en": "A SOC Analyst primarily focuses on:"}', '[{"id": "a", "text": {"en": "Designing overall security architecture"}}, {"id": "b", "text": {"en": "Authorized attacks to find vulnerabilities"}}, {"id": "c", "text": {"en": "Frontline monitoring, investigating alerts, and escalating incidents"}}, {"id": "d", "text": {"en": "Legal compliance frameworks exclusively"}}]', 'c', null, 1),
  ('quick_check', '928490fa-b688-49b9-b6a3-6c918f0332e7', null, null, '{"en": "A Penetration Tester''s work involves:"}', '[{"id": "a", "text": {"en": "Only writing policy documents"}}, {"id": "b", "text": {"en": "Passive monitoring exclusively"}}, {"id": "c", "text": {"en": "Legal compliance work only"}}, {"id": "d", "text": {"en": "Performing authorized attacks to find vulnerabilities before real attackers do"}}]', 'd', null, 2),
  ('quick_check', '928490fa-b688-49b9-b6a3-6c918f0332e7', null, null, '{"en": "A GRC Analyst primarily works on:"}', '[{"id": "a", "text": {"en": "Ensuring an organization meets relevant frameworks and regulations"}}, {"id": "b", "text": {"en": "Writing exploit code"}}, {"id": "c", "text": {"en": "Building firewalls exclusively"}}, {"id": "d", "text": {"en": "Digital forensics investigations"}}]', 'a', null, 3),
  ('quick_check', '928490fa-b688-49b9-b6a3-6c918f0332e7', null, null, '{"en": "Why does the variety of cybersecurity roles matter?"}', '[{"id": "a", "text": {"en": "It doesn''t matter; every role is identical"}}, {"id": "b", "text": {"en": "Different roles suit genuinely different skills and interests"}}, {"id": "c", "text": {"en": "Only one role is actually legitimate"}}, {"id": "d", "text": {"en": "All roles require the exact same daily tasks"}}]', 'b', null, 4),
  ('quick_check', 'a395a10b-c799-4aca-c7b4-7da0a1449af8', null, null, '{"en": "CompTIA Security+ is best described as:"}', '[{"id": "a", "text": {"en": "A senior-level, highly specialized certification"}}, {"id": "b", "text": {"en": "An entry-level certification validating foundational knowledge"}}, {"id": "c", "text": {"en": "Exclusively for penetration testers"}}, {"id": "d", "text": {"en": "A physical security credential"}}]', 'b', null, 1),
  ('quick_check', 'a395a10b-c799-4aca-c7b4-7da0a1449af8', null, null, '{"en": "OSCP is widely respected because:"}', '[{"id": "a", "text": {"en": "It requires actually compromising systems in a hands-on, timed practical exam"}}, {"id": "b", "text": {"en": "It''s entirely multiple-choice with no practical component"}}, {"id": "c", "text": {"en": "It requires no preparation at all"}}, {"id": "d", "text": {"en": "It''s the easiest certification to obtain"}}]', 'a', null, 2),
  ('quick_check', 'a395a10b-c799-4aca-c7b4-7da0a1449af8', null, null, '{"en": "CISSP typically requires:"}', '[{"id": "a", "text": {"en": "No prior experience whatsoever"}}, {"id": "b", "text": {"en": "Only a high school diploma"}}, {"id": "c", "text": {"en": "Passing a purely practical hacking exam"}}, {"id": "d", "text": {"en": "Several years of relevant work experience before eligibility"}}]', 'd', null, 3),
  ('quick_check', 'a395a10b-c799-4aca-c7b4-7da0a1449af8', null, null, '{"en": "The honest truth about certifications, according to this lesson, is that:"}', '[{"id": "a", "text": {"en": "They guarantee a job regardless of skill"}}, {"id": "b", "text": {"en": "They''re completely useless"}}, {"id": "c", "text": {"en": "They open doors but don''t replace genuine, hands-on skill"}}, {"id": "d", "text": {"en": "Only one certification is ever worth pursuing"}}]', 'c', null, 4),
  ('quick_check', 'b4a6b21c-d8aa-4bdb-d8c5-8eb1b255abf9', null, null, '{"en": "A commonly recommended way to build practical skill is to:"}', '[{"id": "a", "text": {"en": "Practice on legal platforms designed for this, like TryHackMe or HackTheBox"}}, {"id": "b", "text": {"en": "Avoid any hands-on practice entirely"}}, {"id": "c", "text": {"en": "Only read certification study guides"}}, {"id": "d", "text": {"en": "Wait until landing a job to learn anything practical"}}]', 'a', null, 1),
  ('quick_check', 'b4a6b21c-d8aa-4bdb-d8c5-8eb1b255abf9', null, null, '{"en": "Why does early breadth (rather than immediate specialization) tend to help?"}', '[{"id": "a", "text": {"en": "It never actually helps"}}, {"id": "b", "text": {"en": "Specialization should always happen immediately"}}, {"id": "c", "text": {"en": "Breadth has no relationship to career direction"}}, {"id": "d", "text": {"en": "You don''t yet know which area genuinely excites you until you''ve been exposed to several"}}]', 'd', null, 2),
  ('quick_check', 'b4a6b21c-d8aa-4bdb-d8c5-8eb1b255abf9', null, null, '{"en": "Networking (professional connections) matters in this field because:"}', '[{"id": "a", "text": {"en": "It has no real impact on opportunities"}}, {"id": "b", "text": {"en": "It''s only useful for non-technical roles"}}, {"id": "c", "text": {"en": "Many opportunities come through people who already know your work"}}, {"id": "d", "text": {"en": "It replaces the need for any technical skill"}}]', 'c', null, 3),
  ('quick_check', 'b4a6b21c-d8aa-4bdb-d8c5-8eb1b255abf9', null, null, '{"en": "According to this lesson, what actually carries a career forward long-term?"}', '[{"id": "a", "text": {"en": "Memorizing every current fact permanently"}}, {"id": "b", "text": {"en": "Understanding why a threat works and how defenses actually address it, not just memorizing specific facts"}}, {"id": "c", "text": {"en": "Avoiding any new information after certification"}}, {"id": "d", "text": {"en": "Ignoring how the field changes over time"}}]', 'b', null, 4);
